const KEYS = ["world", "europe", "asia", "africa", "americas", "oceania"];
const area = (key, inner) => `<g class="ar" data-ar="${key}">${inner}</g>`;
const fy = (x) => FAR.y(x) + 2; // a tree's foot on the far hill
