// Admin mode's state: whether it's unlocked (for this browser tab), and the test games it plays.
// The admin screens themselves (views/admin.js) are only downloaded when someone opens #/admin.
import { CONFIG } from "./config.js";
import { newGame, gameKey } from "./store.js";
import { areaOf } from "./areas.js";
import { esc, html, raw, sha256Hex } from "./util.js";

const KEY = "duskhunt:admin";
let prefs = { unlocked: false, revealAnswer: true, sampleCrowd: false };
try {
  prefs = { ...prefs, ...JSON.parse(sessionStorage.getItem(KEY) || "{}") };
} catch {}
const savePrefs = () => {
  try {
    sessionStorage.setItem(KEY, JSON.stringify(prefs));
  } catch {}
};

const testGames = new Map();

export const admin = {
  get unlocked() {
    return prefs.unlocked;
  },
  get revealAnswer() {
    return prefs.unlocked && prefs.revealAnswer;
  },
  get useSampleCrowd() {
    return prefs.unlocked && prefs.sampleCrowd;
  },
  /** The admin screen's own settings: revealAnswer, sampleCrowd. */
  get prefs() {
    return { ...prefs };
  },
  setPref(key, value) {
    prefs[key] = value;
    savePrefs();
  },
  async unlock(pass) {
    const ok = (await sha256Hex(pass)) === CONFIG.ADMIN_PASSCODE_SHA256;
    if (ok) {
      prefs.unlocked = true;
      savePrefs();
    }
    return ok;
  },
  lock() {
    prefs.unlocked = false;
    savePrefs();
  },
  testGame(day, area = "world") {
    const key = gameKey(day, area);
    if (!testGames.has(key)) testGames.set(key, newGame(day, false, area));
    return testGames.get(key);
  },
  saveTestGame(game) {
    testGames.set(gameKey(game.day, game.area), game);
  },
  resetTestGame(day, area = "world") {
    testGames.delete(gameKey(day, area));
  },
  bannerHtml(puzzle) {
    return html`<div class="admin-banner">
      <span>Test mode · day ${puzzle.day}${puzzle.area !== "world" ? ` · ${areaOf(puzzle.area).name}` : ""} · nothing is saved${raw(this.revealAnswer ? ` · answer: <b>${esc(puzzle.animal.name)}</b>` : "")}</span>
      <span class="row">
        <button class="btn btn-small" type="button" data-admin-action="restart" data-day="${puzzle.day}">Restart</button>
        <a class="btn btn-small" href="#/admin/${puzzle.day}">Admin</a>
      </span>
    </div>`;
  },
};
