// The game's icons.
// • Buttons and labels: Phosphor Icons (MIT licence), two-tone; the paths are in data/ui-icons.js,
//   written by tools/fetch-icons.mjs. They are drawn in a 256 box and take the colour of the text.
// • The speed creatures (a snail for 1/8 speed, a cheetah for real speed) are animal silhouettes
//   like every other animal in the game (shapes.js).
import { UI } from "./data/ui-icons.js";
import { shapeByName } from "./shapes.js";

/** The icons the first screen shows. The published index.html carries these (tools/publish-site.mjs);
 * the rest arrive with the script. */
export const FIRST_ICONS = ["sound-on", "sound-off", "journal", "chart", "help", "play", "globe", "chevron"];

const symbol = (k) => `<symbol id="i-${k}" viewBox="0 0 256 256" fill="currentColor">${UI[k]}</symbol>`;
const sprite = (keys) => `<svg xmlns="http://www.w3.org/2000/svg" style="display:none" aria-hidden="true">${keys.map(symbol).join("")}</svg>`;

/** An <svg> sprite: every icon, or only the ones named. */
export const spriteHtml = (only) => sprite(Object.keys(UI).filter((k) => !only || only.includes(k)));

/** Adds every icon the page doesn't have yet. */
export function injectSprite() {
  const missing = Object.keys(UI).filter((k) => !document.getElementById(`i-${k}`));
  if (!missing.length) return;
  const holder = document.createElement("div");
  holder.innerHTML = sprite(missing);
  document.body.prepend(holder.firstChild);
}

/** <svg> markup for an icon. */
export const icon = (name, cls = "") => `<svg class="i ${cls}" aria-hidden="true"><use href="#i-${name}"/></svg>`;

/** <svg> markup for a speed creature: snail, tortoise, hare, cheetah, owl or bat. */
export const creature = (name, cls = "") => shapeByName(name, `cr${cls ? " " + cls : ""}`);
