import { ANIMAL_LIST } from "./data/animal-list.js";
import { slugify } from "./util.js";

const EMOJI_TAIL = /\s+([\p{Extended_Pictographic}‍️\u{1F3FB}-\u{1F3FF}]+)$/u;

export function normalize(text) {
  return text
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/['’`.]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function parseHeader(line) {
  const [key, label, emoji] = line.slice(1).split("|").map((s) => s.trim());
  return { key, label, emoji: emoji || "" };
}

function parse(text) {
  const entries = [];
  let cls, order, family;
  for (const rawLine of text.split("\n")) {
    const line = rawLine.trim();
    if (!line || line.startsWith("//")) continue;
    if (line[0] === "@") {
      cls = parseHeader(line);
      order = family = null;
      continue;
    }
    if (line[0] === "#") {
      order = parseHeader(line);
      family = null;
      continue;
    }
    if (line[0] === "%") {
      family = parseHeader(line);
      continue;
    }
    for (let chunk of line.split(";")) {
      chunk = chunk.trim();
      if (!chunk) continue;
      let emoji = "";
      const m = chunk.match(EMOJI_TAIL);
      if (m) {
        emoji = m[1];
        chunk = chunk.slice(0, m.index).trim();
      }
      const [name, aliasText = ""] = chunk.split("=");
      const aliases = aliasText.split(",").map((a) => a.trim()).filter(Boolean);
      const fam = family || { key: `${order?.key}-misc`, label: order?.label || cls.label, emoji: "" };
      const ord = order || { key: `${cls.key}-misc`, label: cls.label, emoji: "" };
      entries.push({
        id: slugify(name.trim()),
        name: name.trim(),
        aliases,
        emoji: emoji || fam.emoji || ord.emoji || cls.emoji,
        ownEmoji: Boolean(emoji),
        cls,
        order: ord,
        family: fam,
        terms: [normalize(name), ...aliases.map(normalize)],
      });
    }
  }
  return entries;
}

export const ANIMALS = parse(ANIMAL_LIST);

// ---------- Everyday words (easy mode) ----------
// In easy mode the everyday name is enough: "toad" for an American toad, "owl" for a barn owl,
// "cricket" for a mole cricket. The everyday word is the last word of the name, within the same
// class: a cow is still a cow and not a sheep, a lion is not a cat. A few two-word kinds stay whole
// ("sea lion", "guinea pig", "flying fox", which is a bat and not a fox). A hyphenated last word
// only counts as its end when that end is an animal of its own (an eagle-owl is an owl, a
// bush-cricket a cricket); otherwise it stays whole (a bee-eater, a dik-dik). Answers can add the
// words people use that aren't in the name (`easy` in answers.js: a mallard is a duck).
// Two-word kinds that aren't the second word's animal (a sea otter is an otter; a sea lion isn't a lion).
const COMPOUND = new Set(["sea lion", "sea cow", "sea spider", "sea butterfly", "sea angel", "sea hare", "sea mouse", "sea wasp", "flying fox", "guinea pig", "raccoon dog", "prairie dog", "brush turkey"]);
// Names whose last word isn't what the animal is called (a Gila monster isn't a "monster").
const WHOLE = new Set(
  ["Tasmanian devil", "Thorny devil", "Sugar glider", "Wild ass", "Red river hog", "Boa constrictor", "Slow worm", "Gila monster", "Red-eared slider",
   "Painted lady", "Red admiral", "Blue morpho", "Cabbage white", "Stick insect", "Leaf insect", "Water strider", "Lesser water boatman", "Black widow",
   "Brown recluse", "Sand hopper", "Water flea", "Brine shrimp", "Horseshoe crab", "Box jellyfish", "Comb jelly", "Portuguese man o' war", "Flying fish",
   "Black drum", "Blue tang", "Arctic char"].map(normalize),
);
const capital = (s) => s[0].toUpperCase() + s.slice(1);
let plain = null; // the last words of names that don't end in a hyphenated word
function everydayOf(fullName) {
  plain ||= new Set(ANIMALS.map((a) => a.name.split(" ").at(-1)).filter((w) => !w.includes("-")).map(normalize));
  const name = fullName.replace(/\s*\([^)]*\)/g, ""); // "Hydra (animal)"
  if (WHOLE.has(normalize(name))) return { word: normalize(name), label: name };
  const words = name.split(" ");
  let last = words.at(-1);
  let before = words.at(-2);
  if (last.includes("-")) {
    const parts = last.split("-");
    if (plain.has(normalize(parts.at(-1)))) [before, last] = [parts.at(-2), parts.at(-1)];
  }
  const label = before && COMPOUND.has(normalize(`${before} ${last}`)) ? `${before} ${last}` : last;
  return { word: normalize(label), label: capital(label.toLowerCase()) };
}
export const everyday = (name) => everydayOf(name).word;

const NOT_KINDS = new Set(["Thing", "Mythical", "Dinosauria", "Pterosauria"]);
const examples = (members) => {
  const shown = members.slice(0, 3).map((m) => m.name);
  return `${shown.join(", ")}${members.length > shown.length ? ` and ${members.length - shown.length} more` : ""}`;
};

function groupsBy(keyOf, min = 2) {
  const map = new Map();
  for (const a of ANIMALS) {
    if (NOT_KINDS.has(a.cls.key)) continue;
    const key = keyOf(a);
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(a);
  }
  return [...map.values()].filter((members) => members.length >= min);
}

/**
 * Easy mode's guesses: one per everyday word in each class, like "Toad" (any toad) or "Lion". The
 * search in easy mode only offers these, never the species' long names, but typing a species' name
 * or nickname finds its word ("cane toad" finds "Toad"). In BY_ID, so guesses and results can show
 * them, but never in ANIMALS: normal and hard mode don't offer them. `words` is what a group counts
 * as; a group of one ("Lion") is that animal.
 */
export const GROUPS = groupsBy((a) => `${a.cls.key}/${everyday(a.name)}`, 1).map((members) => {
  const { cls, order } = members[0];
  const { word, label } = everydayOf(members[0].name);
  const same = (level) => members.every((m) => m[level].key === members[0][level].key);
  return {
    // The first member's order is in the id, so ids from before sharks were one group still work.
    id: `kind-${slugify(`${order.key} ${word}`)}`,
    name: label,
    aliases: [],
    emoji: members.find((m) => m.ownEmoji)?.emoji || members[0].emoji,
    ownEmoji: false,
    cls,
    // Owls or toads from several families (or sharks from several orders) sit beside them.
    order: same("order") ? order : { key: `kind-${word}`, label: `${label}s`, emoji: "" },
    family: same("family") ? members[0].family : { key: `kind-${word}`, label: `${label}s`, emoji: "" },
    group: true,
    members: members.map((m) => m.id),
    words: new Set([word]),
    examples: members.length > 1 ? `Any ${word} · ${cls.label}` : cls.label,
    // The word itself first; then every member's name and nicknames, so they find it too.
    terms: [...new Set([word, ...members.flatMap((m) => m.terms)])],
  };
});

/** Everything easy mode's search offers: the everyday words, plus the silly and extinct guesses as they are. */
const EASY_GUESSES = [...GROUPS, ...ANIMALS.filter((a) => NOT_KINDS.has(a.cls.key))];

// Whole families were easy mode's groups for its first hour live (2026-09-27). Kept so a game saved
// then still shows its guesses; never offered.
const RETIRED = groupsBy((a) => `${a.cls.key}/${a.family.key}`).map((members) => ({
  id: `family-${slugify(members[0].family.key)}`,
  name: members[0].family.label,
  aliases: [],
  emoji: members[0].family.emoji || members[0].order.emoji || members[0].cls.emoji,
  ownEmoji: false,
  cls: members[0].cls,
  order: members[0].order,
  family: members[0].family,
  group: true,
  retired: true,
  words: new Set(members.map((m) => everyday(m.name))),
  examples: `Whole family · ${examples(members)}`,
  terms: [],
}));

export const BY_ID = new Map([...ANIMALS, ...GROUPS, ...RETIRED].map((a) => [a.id, a]));

if (BY_ID.size !== ANIMALS.length + GROUPS.length + RETIRED.length) {
  const seen = new Set();
  for (const a of [...ANIMALS, ...GROUPS, ...RETIRED]) {
    if (seen.has(a.id)) console.warn("Duplicate animal id:", a.id);
    seen.add(a.id);
  }
}

// ---------- Search ----------

function editDistance(a, b, max) {
  if (Math.abs(a.length - b.length) > max) return max + 1;
  const prev2 = new Array(b.length + 1);
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    let rowMin = i;
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      let v = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost);
      if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) v = Math.min(v, prev2[j - 2] + 1);
      cur[j] = v;
      if (v < rowMin) rowMin = v;
    }
    if (rowMin > max) return max + 1;
    for (let j = 0; j <= b.length; j++) prev2[j] = prev[j];
    prev = cur;
  }
  return prev[b.length];
}

function scoreTerm(q, qTokens, term) {
  if (term === q) return 1000;
  if (term.startsWith(q)) return 800 - (term.length - q.length);
  const words = term.split(" ");
  if (qTokens.every((t) => words.some((w) => w.startsWith(t)))) return 600 - term.length;
  if (term.includes(q)) return 400 - term.length;
  if (q.length < 3) return 0;
  const max = q.length <= 4 ? 1 : q.length <= 7 ? 2 : 3;
  let best = editDistance(q, term, max);
  best = Math.min(best, editDistance(q, term.slice(0, q.length), max));
  for (const w of words) if (w.length >= 3) best = Math.min(best, editDistance(q, w, max));
  if (best <= max) return 250 - best * 60 - term.length * 0.5;
  return 0;
}

/**
 * Fuzzy search across every name and alias.
 * Returns [{ animal, alias }] where alias is the matched nickname (if it wasn't the main name).
 * With groups (easy mode), only the everyday words are offered ("Toad"), found by their own word
 * or by any member's name.
 */
export function search(query, { limit = 8, exclude = new Set(), groups = false } = {}) {
  const q = normalize(query);
  if (!q) return [];
  const qTokens = q.split(" ");
  const hits = [];
  for (const animal of groups ? EASY_GUESSES : ANIMALS) {
    if (exclude.has(animal.id)) continue;
    let best = 0;
    let alias = null;
    animal.terms.forEach((term, i) => {
      // An easy-mode word is found by the word itself (typos and all), or by the start of one of
      // its animals' names ("cane toad" finds "Toad"), never by a guess at a hidden name.
      if (animal.group && i > 0 && !term.startsWith(q)) return;
      const s = scoreTerm(q, qTokens, term) - (i === 0 ? 0 : 15);
      if (s > best) {
        best = s;
        alias = i === 0 || animal.group ? null : animal.aliases[i - 1];
      }
    });
    if (best > 0) hits.push({ animal, alias, score: best });
  }
  hits.sort((a, b) => b.score - a.score || a.animal.name.length - b.animal.name.length || a.animal.name.localeCompare(b.animal.name));
  return hits.slice(0, limit);
}

// ---------- Closeness ----------

export const LEVELS = {
  correct: { rank: 4, tone: "correct" },
  family: { rank: 3, tone: "family" },
  order: { rank: 2, tone: "order" },
  class: { rank: 1, tone: "class" },
  none: { rank: 0, tone: "none" },
  skip: { rank: -1, tone: "skip" },
};

/** "a mammal" / "an insect" */
export const withArticle = (word) => (/^(?!eu|uni|use|one)[aeiou]/i.test(word) ? `an ${word}` : `a ${word}`);

// Names inside a sentence: "a common toad", but "an American toad" and "a Steller's sea eagle".
const PROPER = /^(American|European|Eurasian|African|Asian|Arctic|Antarctic|Canada|Canadian|California|Indian|Australian|Andean|Ethiopian|Siberian|Japanese|Chinese|Tasmanian|Bengal|Himalayan|Atlantic|Pacific|Nile|Amazon|Mexican|Egyptian|Caspian|Baltic|Humboldt|Magellanic|Adélie|Victoria|Barbary|Bornean|Sumatran|Malagasy|Madagascar|Philippine|Norway|Hawaiian|Galápagos|Iberian|Scottish|Irish|English|Russian|Mediterranean|Caribbean|Brazilian|Chilean|Patagonian|Mongolian|Tibetan|Persian)$|'s$/;
export const lowerName = (name) =>
  name
    .split(" ")
    .map((w) => (PROPER.test(w) ? w : w.toLowerCase()))
    .join(" ");

export function closeness(guessId, answerId) {
  if (guessId == null) return { level: "skip", text: "Skipped. Speeding up…" };
  const g = BY_ID.get(guessId);
  const a = BY_ID.get(answerId);
  if (!g || !a) return { level: "none", text: "Unknown guess" };
  if (g.id === a.id) return { level: "correct", text: "That's it!" };
  const sameClass = g.cls.key === a.cls.key;
  if (sameClass && g.family.key === a.family.key) return { level: "family", text: `Same family: ${a.family.label.toLowerCase()}` };
  if (sameClass && g.order.key === a.order.key) return { level: "order", text: `Same group: ${a.order.label.toLowerCase()}` };
  if (sameClass) return { level: "class", text: `Right class. It's ${withArticle(a.cls.label.toLowerCase())}` };
  if (g.cls.key === "Thing") return { level: "none", text: "Not even alive. It's a real animal" };
  if (g.cls.key === "Mythical") return { level: "none", text: "Mythical. The mystery animal is real" };
  if (g.cls.key === "Dinosauria" || g.cls.key === "Pterosauria") return { level: "none", text: "Extinct. The mystery animal is alive" };
  return { level: "none", text: `The mystery animal isn't ${withArticle(g.cls.label.toLowerCase())}` };
}

export function groupLabel(animal) {
  if (animal.group) return animal.examples;
  if (animal.cls.key === "Thing" || animal.cls.key === "Mythical") return animal.cls.label;
  return `${animal.cls.label} · ${animal.family.label}`;
}
