// A call's picture: how strong each pitch is at each moment of the clip, as a small grid
// (time across, pitch up). The sound ring around the play button draws it as the call plays
// (components/visualizer.js). It's worked out once from the recording itself, not from what the
// speakers are doing, so it looks the same at every speed and the background hiss of a field
// recording is taken out: only the call leaves marks.

/** In-place FFT of a power-of-two length (real and imaginary parts). */
function fft(re, im) {
  const N = re.length;
  for (let i = 1, j = 0; i < N; i++) {
    let bit = N >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= N; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    const wr = Math.cos(ang);
    const wi = Math.sin(ang);
    for (let i = 0; i < N; i += len) {
      let cr = 1;
      let ci = 0;
      for (let k = 0; k < len / 2; k++) {
        const a = i + k;
        const b = a + len / 2;
        const xr = re[b] * cr - im[b] * ci;
        const xi = re[b] * ci + im[b] * cr;
        re[b] = re[a] - xr;
        im[b] = im[a] - xi;
        re[a] += xr;
        im[a] += xi;
        const t = cr * wr - ci * wi;
        ci = cr * wi + ci * wr;
        cr = t;
      }
    }
  }
}

const quantile = (sorted, q) => sorted[Math.min(sorted.length - 1, Math.max(0, Math.floor(q * (sorted.length - 1))))];

/**
 * The picture of len seconds of buffer from start: { cols, rows, data } with data[c * rows + r]
 * from 0 (nothing) to 1 (the loudest), r = 0 the lowest pitch. The band runs from low to high Hz,
 * spaced the way ears hear (each row the same musical step).
 */
export function soundPrint(buffer, start, len, { cols = 180, rows = 20, low = 150, high = 9000 } = {}) {
  const sr = buffer.sampleRate;
  const N = 1024;
  const a = buffer.getChannelData(0);
  const b = buffer.numberOfChannels > 1 ? buffer.getChannelData(1) : null;
  const first = Math.floor(start * sr);
  const total = Math.floor(len * sr);
  const hann = Float32Array.from({ length: N }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (N - 1)));
  const re = new Float32Array(N);
  const im = new Float32Array(N);
  const top = Math.min(high, sr / 2 - 1);
  const edge = Array.from({ length: rows + 1 }, (_, r) => (low * (top / low) ** (r / rows) * N) / sr);
  const db = new Float32Array(cols * rows);

  for (let c = 0; c < cols; c++) {
    const from = first + Math.round(((c + 0.5) / cols) * total) - N / 2;
    for (let i = 0; i < N; i++) {
      const k = from + i;
      const v = k >= 0 && k < a.length ? (b ? (a[k] + b[k]) / 2 : a[k]) : 0;
      re[i] = v * hann[i];
      im[i] = 0;
    }
    fft(re, im);
    for (let r = 0; r < rows; r++) {
      let p = 0;
      for (let k = Math.floor(edge[r]); k <= Math.min(N / 2 - 1, Math.ceil(edge[r + 1])); k++) p = Math.max(p, re[k] * re[k] + im[k] * im[k]);
      db[c * rows + r] = 10 * Math.log10(p + 1e-12);
    }
  }

  // The hiss: quiet in most of the grid. A row's own floor takes out a steady hum at that pitch, but
  // never more than a little above the overall floor, or a steady call (a cicada) would vanish too.
  const overall = quantile(Float32Array.from(db).sort(), 0.1);
  const col = new Float32Array(cols);
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) col[c] = db[c * rows + r];
    const floor = Math.min(quantile(Float32Array.from(col).sort(), 0.25), overall + 10);
    for (let c = 0; c < cols; c++) db[c * rows + r] -= floor;
  }
  const peak = quantile(Float32Array.from(db).sort(), 0.995);
  const span = Math.max(14, peak - 6);
  const data = new Float32Array(cols * rows);
  for (let i = 0; i < data.length; i++) data[i] = Math.min(1, Math.max(0, (db[i] - 6) / span));
  return { cols, rows, data };
}
