// The sound ring around the play button. As the call plays it draws its own picture: time runs
// clockwise from the top (one turn is the whole clip), pitch runs outwards (low notes near the
// button, high ones at the rim), and louder is darker, with the loudest parts in the warm accent.
// A chirp is a row of marks, a howl a long sweep. The finished ring stays until the next play, so
// the rhythm can be read as well as heard. The picture is the same at every speed (soundprint.js);
// slowed down, it just takes longer to draw.
import { setAmp } from "../scene.js";

const TOP = -Math.PI / 2;
const TURN = Math.PI * 2;

/** clip(): the loaded Clip (audio.js), or null while it's loading. */
export function createVisualizer(canvas, { clip }) {
  const g = canvas.getContext("2d");
  // The picture so far, kept between frames in white: all of it, and its loudest parts. Each frame
  // they're laid on the screen in the colours of the hour (the ink changes as the sky does).
  const all = document.createElement("canvas");
  const loud = document.createElement("canvas");
  const tint = document.createElement("canvas");
  const ag = all.getContext("2d");
  const lg = loud.getContext("2d");
  const tg = tint.getContext("2d");
  let raf = 0;
  let timer = 0;
  let frame = 0;
  let size = 0; // CSS px
  let dpr = 1;
  let done = 0; // columns of the picture drawn in this play
  let lastAt = null; // where the play was last frame (0…1); null between plays
  let hasPicture = false;
  let t = 0;
  let colors = { ink: "#1b2340", hot: "#e0503f" };
  let lastHour = document.documentElement.dataset.time;
  let hourChanged = -1e9;

  function readColors() {
    const css = getComputedStyle(document.documentElement);
    colors = { ink: css.getPropertyValue("--on-sky").trim() || colors.ink, hot: css.getPropertyValue("--accent").trim() || colors.hot };
  }

  const cssW = () => canvas.width / dpr;
  const cssH = () => canvas.height / dpr;
  const wipe = (c) => c.clearRect(0, 0, cssW(), cssH());

  /** Fits the canvases to the ring. again: the ring is already running (the window changed). */
  function resize(again = true) {
    const ratio = window.devicePixelRatio || 1;
    const box = canvas.getBoundingClientRect();
    const w = Math.round(box.width * ratio);
    const h = Math.round(box.height * ratio);
    // A phone's browser bar sliding away also counts as a resize. The ring is as big as it was
    // then, and sizing a canvas wipes it: leave it alone, or the finished picture would vanish.
    if (again && w === canvas.width && h === canvas.height && ratio === dpr) return;
    dpr = ratio;
    size = Math.min(box.width, box.height);
    for (const c of [canvas, all, loud, tint]) {
      c.width = w;
      c.height = h;
    }
    for (const c of [g, ag, lg, tg]) c.setTransform(dpr, 0, 0, dpr, 0, 0);
    // A really new size (the phone turned): the picture so far is drawn again at that size, and
    // shown in this same frame instead of after the idle wait.
    const print = hasPicture ? clip()?.print() : null;
    if (print) columns(print, 0, done);
    else {
      done = 0;
      lastAt = null;
      hasPicture = false;
    }
    if (again) {
      clearTimeout(timer);
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(draw);
    }
  }

  /** Columns from..to of the picture, each a thin wedge with an arc in every ring of pitch. */
  function columns(print, from, to) {
    const inner = size * 0.33;
    const th = (size * 0.475 - inner) / print.rows;
    const cx = cssW() / 2;
    const cy = cssH() / 2;
    for (let c = from; c < to; c++) {
      const a0 = TOP + (c / print.cols) * TURN;
      const a1 = TOP + ((c + 1) / print.cols) * TURN + 0.004;
      for (let r = 0; r < print.rows; r++) {
        const v = print.data[c * print.rows + r];
        if (v < 0.05) continue;
        for (const [ctx, alpha] of [[ag, v ** 1.25], [lg, v > 0.72 ? (v - 0.72) / 0.28 : 0]]) {
          if (!alpha) continue;
          ctx.globalAlpha = alpha;
          ctx.strokeStyle = "#fff";
          ctx.lineWidth = th + 0.5;
          ctx.beginPath();
          ctx.arc(cx, cy, inner + (r + 0.5) * th, a0, a1);
          ctx.stroke();
        }
      }
    }
  }

  /** Lays a white layer onto the screen in one colour. */
  function lay(layer, color, alpha) {
    wipe(tg);
    tg.globalCompositeOperation = "source-over";
    tg.drawImage(layer, 0, 0, cssW(), cssH());
    tg.globalCompositeOperation = "source-in";
    tg.fillStyle = color;
    tg.fillRect(0, 0, cssW(), cssH());
    g.globalAlpha = alpha;
    g.drawImage(tint, 0, 0, cssW(), cssH());
    g.globalAlpha = 1;
  }

  function draw() {
    // The ink follows the sky's hour: read on every frame while the hour is changing (the colours
    // glide for a good second), and now and then otherwise.
    const hour = document.documentElement.dataset.time;
    if (hour !== lastHour) {
      lastHour = hour;
      hourChanged = performance.now();
    }
    if (frame++ % 20 === 0 || performance.now() - hourChanged < 2200) readColors();
    const c = clip();
    const at = c?.playing ? c.position : null;
    const cx = cssW() / 2;
    const cy = cssH() / 2;
    const inner = size * 0.33;
    const outer = size * 0.475;
    let level = 0;

    if (at != null) {
      const print = c.print();
      if (lastAt == null || at < lastAt - 0.01) {
        // A new play starts a new picture.
        wipe(ag);
        wipe(lg);
        done = 0;
        hasPicture = true;
      }
      const upTo = Math.min(print.cols, Math.ceil(at * print.cols));
      if (upTo > done) {
        columns(print, done, upTo);
        done = upTo;
      }
      // How loud this moment is, for the grass and the fireflies.
      const col = Math.min(print.cols - 1, Math.floor(at * print.cols));
      for (let r = 0; r < print.rows; r++) level += print.data[col * print.rows + r];
      level /= print.rows;
      lastAt = at;
    } else lastAt = null;

    wipe(g);
    // The empty track: a ring of small ticks that breathes while it waits, and fades once there's a picture.
    t += 0.016;
    g.lineCap = "round";
    g.strokeStyle = colors.ink;
    g.lineWidth = 3;
    const ticks = 56;
    for (let i = 0; i < ticks; i++) {
      const a = TOP + (i / ticks) * TURN;
      const len = hasPicture ? 2 : 5 + 2 * Math.sin(t * 1.6 + i * 0.45);
      g.globalAlpha = hasPicture ? 0.16 : 0.3;
      g.beginPath();
      g.moveTo(cx + Math.cos(a) * inner, cy + Math.sin(a) * inner);
      g.lineTo(cx + Math.cos(a) * (inner + len), cy + Math.sin(a) * (inner + len));
      g.stroke();
    }
    g.globalAlpha = 1;
    if (hasPicture) {
      lay(all, colors.ink, at != null ? 0.92 : 0.72);
      lay(loud, colors.hot, at != null ? 1 : 0.8);
    }
    if (at != null) {
      // Where the play has got to: a small bright bead on the rim.
      const a = TOP + at * TURN;
      g.fillStyle = colors.hot;
      g.beginPath();
      g.arc(cx + Math.cos(a) * (outer + 3), cy + Math.sin(a) * (outer + 3), 3.2, 0, TURN);
      g.fill();
    }
    setAmp(at != null ? Math.min(1, level * 3) : 0);
    schedule(at != null);
  }

  function schedule(playing) {
    if (document.hidden) return;
    if (playing) raf = requestAnimationFrame(draw);
    else timer = setTimeout(() => (raf = requestAnimationFrame(draw)), 90);
  }
  function onVisibility() {
    if (!document.hidden) {
      clearTimeout(timer);
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(draw);
    }
  }

  readColors();
  resize(false);
  const onResize = () => resize();
  window.addEventListener("resize", onResize);
  document.addEventListener("visibilitychange", onVisibility);
  raf = requestAnimationFrame(draw);
  return () => {
    cancelAnimationFrame(raf);
    clearTimeout(timer);
    setAmp(0);
    window.removeEventListener("resize", onResize);
    document.removeEventListener("visibilitychange", onVisibility);
  };
}
