const named = new Map();

/** The name of the silhouette for an animal (an entry from animals.js, or its id). */
export function shapeOf(animal) {
  if (typeof animal === "string") animal = BY_ID.get(animal);
  if (!animal) return "paw";
  if (named.has(animal.id)) return named.get(animal.id);
  // An everyday word ("Toad · any toad") looks like its first animal.
  const one = animal.members?.length ? BY_ID.get(animal.members[0]) || animal : animal;
  const parts = one.id.split("-");
  const tries = [ID[one.id], one.id, ...parts.slice(1).map((_, i) => parts.slice(i + 1).join("-")), FAMILY[one.family?.key], ORDER[one.order?.key], CLASS[one.cls?.key]];
  const name = tries.find((n) => n && HAVE.has(n)) || (one.cls?.key === "Thing" ? "sound" : "paw");
  named.set(animal.id, name);
  return name;
}

/** For tools/silhouettes/check.mjs: the tables, to find entries that point at nothing. */
export const TABLES = { ID, FAMILY, ORDER, CLASS };

// ---------- Fetching and drawing ----------
// Every silhouette is one small file (about 3 KB), fetched the first time it is shown and kept for
// the rest of the visit; the published copy also keeps them on the device (sw.js).

export const BOX = 640; // the box every silhouette is drawn in
const GROUND = 590; // where a standing animal's feet go
const HOVER = 150; // how far above that a flying one floats

const ready = new Map(); // name → { d, t, box, fly }
const loading = new Map();

function read(text) {
  const d = /<path[^>]* d="([^"]+)"/.exec(text)?.[1];
  if (!d) return null;
  const box = (/data-box="([^"]+)"/.exec(text)?.[1] || `0 0 ${BOX} ${BOX}`).split(" ").map(Number);
  return { d, t: /<path[^>]* transform="([^"]+)"/.exec(text)?.[1] || "", box, fly: text.includes("data-fly") };
}

/** The silhouette called `name`: { d, t, box: [left, top, right, bottom], fly }, or null if it can't be had. */
export function loadShape(name) {
  if (ready.has(name)) return Promise.resolve(ready.get(name));
  if (!loading.has(name)) {
    loading.set(name, fetch(`shapes/${name}.svg`)
      .then((r) => (r.ok ? r.text() : Promise.reject(new Error(String(r.status)))))
      .then((text) => {
        const s = read(text);
        if (s) ready.set(name, s);
        return s;
      })
      .catch(() => {
        loading.delete(name); // offline for a moment: try again the next time it's shown
        return null;
      }));
  }
  return loading.get(name);
}


/** The path of a loaded silhouette, for drawing inside another <svg>. */
export const shapePath = (s) => `<path d="${s.d}"${s.t ? ` transform="${s.t}"` : ""}/>`;

/** How far down a loaded silhouette has to move to stand on the ground line (or float above it). */
export const standShift = (s) => GROUND - s.box[3] - (s.fly ? HOVER : 0);

const viewBox = (s, stand) => `0 ${stand && s ? -standShift(s) : 0} ${BOX} ${BOX}`;

/** The silhouette as an <svg> that takes the colour of the text around it. It is filled in as soon
 * as its file has arrived. With the class "stand" its feet are on the bottom edge, as on a ridge;
 * otherwise it sits in the middle of its box. */
export function shapeSvg(animal, cls = "") {
  const name = typeof animal === "string" && HAVE.has(animal) && !BY_ID.has(animal) ? animal : shapeOf(animal);
  const s = ready.get(name);
  return `<svg class="shape${cls ? " " + cls : ""}" data-s="${name}" viewBox="${viewBox(s, / ?stand/.test(cls))}" aria-hidden="true">${s ? shapePath(s) : ""}</svg>`;
}

/** A silhouette by its file name (the speed creatures: snail, tortoise, hare, cheetah, owl, bat). */
export const shapeByName = (name, cls = "") => {
  const s = ready.get(name);
  return `<svg class="shape${cls ? " " + cls : ""}" data-s="${name}" viewBox="${viewBox(s, false)}" aria-hidden="true">${s ? shapePath(s) : ""}</svg>`;
};

function fill(svg, again = 2) {
  if (svg.firstChild) return;
  const name = svg.dataset.s;
  loadShape(name).then((s) => {
    if (svg.dataset.s !== name || svg.firstChild || !svg.isConnected) return;
    if (!s) {
      // The connection dropped for a moment: ask again while it's still on the page.
      if (again) setTimeout(() => fill(svg, again - 1), 2500);
      return;
    }
    svg.innerHTML = shapePath(s);
    if (svg.classList.contains("stand")) svg.setAttribute("viewBox", viewBox(s, true));
  });
}

// Any silhouette that lands on the page empty is filled in from here.
if (typeof document !== "undefined" && typeof MutationObserver !== "undefined") {
  const scan = (root) => {
    if (root.matches?.("svg.shape[data-s]")) fill(root);
    root.querySelectorAll?.("svg.shape[data-s]").forEach((el) => fill(el));
  };
  new MutationObserver((list) => {
    for (const m of list) for (const n of m.addedNodes) if (n.nodeType === 1) scan(n);
  }).observe(document.documentElement, { childList: true, subtree: true });
  scan(document.documentElement);
}
