// The sky of the day. Every day has its own: how many clouds and where, how many birds, the real
// phase of the moon, and now and then some mist, a breeze, a rainbow or shooting stars. It's worked
// out from the day's number, so everyone sees the same sky on the same day.
// This file stands alone (no imports): the published page also runs it in a tiny inline script right
// after the landscape's markup, so the day's sky is there with the first paint (tools/publish-site.mjs).

function rand(seed) {
  let a = seed | 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export const CLOUDS = 6; // cloud slots in the landscape; a day uses some of them
export const FLOCKS = 3; // bird flocks along the horizon

const SYNODIC = 29.530588853; // days from new moon to new moon
const NEW_MOON = Date.UTC(2000, 0, 6, 18, 14) / 864e5; // a known new moon, in days

/** 0 = new moon, 0.5 = full, back to 1. noonUtc: that day's noon, UTC, in ms. */
export const moonPhase = (noonUtc) => (((noonUtc / 864e5 - NEW_MOON) / SYNODIC) % 1 + 1) % 1;

/** The lit part of a moon of radius r, as a path: a half disc on the lit side, closed by the
 * terminator. Waxing moons are lit on the right. Never thinner than a sliver, so the night always
 * has its moon. */
export function moonPath(phase, r = 21) {
  const p = Math.min(0.94, Math.max(0.06, phase));
  const waxing = p <= 0.5;
  const rx = (r * Math.abs(Math.cos(2 * Math.PI * p))).toFixed(2);
  const gibbous = p > 0.25 && p < 0.75;
  const limb = waxing ? 1 : 0; // which way round the edge
  const term = waxing === gibbous ? 1 : 0; // which way the terminator bulges
  return `M0 ${-r}A${r} ${r} 0 0 ${limb} 0 ${r}A${rx} ${r} 0 0 ${term} 0 ${-r}Z`;
}

/** The sky for a day. noonUtc is that day's noon (UTC, ms), for the moon. */
export function skyFor(day, noonUtc) {
  const r = rand(7919 * (day | 0) + 20260901);
  const pick = (list) => list[Math.floor(r() * list.length)];
  const count = pick([2, 3, 3, 3, 4, 4, 5, 1]);
  // Which slots are out today, and how each cloud looks.
  // (A shuffle by hand: sorting with a random comparison gives different results in different browsers.)
  const order = Array.from({ length: CLOUDS }, (_, i) => i);
  for (let i = CLOUDS - 1; i > 0; i--) {
    const j = Math.floor(r() * (i + 1));
    [order[i], order[j]] = [order[j], order[i]];
  }
  const clouds = Array.from({ length: CLOUDS }, (_, i) => {
    const dur = 170 + r() * 150;
    const y = Math.round(110 + r() * 190), s = +(0.8 + r() * 0.9).toFixed(2);
    // y is the cloud's flat base; a big one is kept low enough for its whole heap to show.
    return { on: order.indexOf(i) < count, y: Math.max(y, Math.round(72 * s + 14)), s, dur: Math.round(dur), delay: -Math.round(r() * dur) };
  });
  const flocks = pick([1, 1, 2, 2, 2, 3]);
  const roll = r();
  return {
    clouds,
    flocks,
    mist: roll < 0.2, // a misty day
    breeze: roll >= 0.2 && roll < 0.42, // seeds on the wind
    rainbow: roll >= 0.42 && roll < 0.47, // rare
    meteors: r() < 0.34, // shooting stars that night
    moon: moonPhase(noonUtc),
  };
}

/** Dresses the landscape's <svg> in a day's sky. Only touches attributes, so it's instant. */
export function applySky(svg, sky) {
  if (!svg) return;
  svg.querySelectorAll(".cloud").forEach((el, i) => {
    const c = sky.clouds[i];
    if (!c) return;
    el.style.cssText = `--y:${c.y}px;--s:${c.s};animation-duration:${c.dur}s;animation-delay:${c.delay}s${c.on ? "" : ";display:none"}`;
  });
  svg.querySelectorAll(".flock").forEach((el, i) => (el.style.display = i < sky.flocks ? "" : "none"));
  for (const k of ["mist", "breeze", "rainbow", "meteors"]) svg.classList.toggle(`sky-${k}`, Boolean(sky[k]));
  svg.querySelector(".moon-lit")?.setAttribute("d", moonPath(sky.moon));
}
