import { flushPending } from "./stats.js";
import { injectSprite, icon } from "./icons.js";
import { mountScene, setSceneMode, setTime, setArea } from "./scene.js";
import { sfx } from "./sfx.js";
import { renderGame } from "./views/play.js";
import { admin } from "./admin-mode.js";
import { showHelp, showStats, showCredits, closeModal } from "./views/modals.js";
import { loadAreaPicker } from "./components/areapick.js";
import { store } from "./store.js";
import { AREA_KEYS } from "./areas.js";
import { CONFIG } from "./config.js";
import { $, todayDay, whenIdle, toast } from "./util.js";

// A shared result links to its part of the world (?region=europe), so a friend who taps it hears the
// same animal. It becomes their choice, as if they'd picked it, and leaves the address.
const linked = new URLSearchParams(location.search).get("region");
if (linked !== null) {
  if (AREA_KEYS.includes(linked)) store.area = linked;
  history.replaceState(null, "", location.pathname + location.hash);
}

injectSprite();
mountScene($("#scene"));
if (CONFIG.OFFLINE && "serviceWorker" in navigator) whenIdle(() => navigator.serviceWorker.register("sw.js").catch(() => {}));

const hero = $("#hero");
const view = $("#view");
let cleanup = null;
let routeId = 0;
let drawnDay = todayDay(); // the day the current page was drawn for

// The page starts with <html data-boot> (index.html), which keeps everything from gliding while the
// saved game's hour, part of the world and screen are put in place (js/boot.js has set most of it
// before the first paint). Once the first screen has been drawn, two frames on, gliding is back.
let booting = document.documentElement.hasAttribute("data-boot");
function booted() {
  if (!booting) return;
  booting = false;
  requestAnimationFrame(() => requestAnimationFrame(() => document.documentElement.removeAttribute("data-boot")));
}

// Screens most visits never open (past days, admin) are their own small files, fetched when first
// needed. If the player has moved on by the time one arrives, it isn't drawn.
const loadArchive = () => import("./views/archive.js");
const loadAdmin = () => import("./views/admin.js");
function lazy(load, render) {
  const id = routeId;
  load()
    .then((m) => id === routeId && (cleanup = render(m) || null))
    .catch(() => toast("Couldn't load that page. Check your connection and try again."))
    .finally(booted);
}

// Routes:
//   #/               today's animal (start screen → game → results)
//   #/day/N          a past day from the archive
//   #/replay/N       play a day again just for fun (first result still counts)
//   #/archive        every day so far
//   #/admin[/N]      admin (passcode), optionally with day N selected
//   #/admin/play/N   admin test play of any day, even future ones
// Days are played in the part of the world you've picked (store.area, changed on the map).
function route() {
  routeId++;
  closeModal();
  cleanup?.();
  cleanup = null;
  window.scrollTo(0, 0);
  const parts = location.hash.replace(/^#\/?/, "").split("/").filter(Boolean);
  const today = todayDay();
  drawnDay = today;
  const num = (s) => (/^\d+$/.test(s || "") ? Number(s) : NaN);
  const ctx = { hero, view };
  const area = store.area;
  setArea(area); // its home, trees and colours in the landscape

  if (today < 1) {
    setSceneMode("tall");
    setTime(0);
    hero.innerHTML = `<div class="intro"><h1>Dusk Hunt</h1><p class="tag-line">The zoo hasn't opened yet. Come back on launch day.</p></div>`;
    view.innerHTML = "";
    booted();
    return;
  }

  switch (parts[0]) {
    case undefined:
      cleanup = renderGame({ ...ctx, day: today, mode: "today", area });
      break;
    case "day": {
      const day = num(parts[1]);
      if (!(day >= 1)) return (location.hash = "#/archive");
      if (day >= today) return (location.hash = "#/");
      cleanup = renderGame({ ...ctx, day, mode: "archive", area });
      break;
    }
    case "replay": {
      const day = num(parts[1]);
      if (!(day >= 1) || day > today) return (location.hash = "#/");
      cleanup = renderGame({ ...ctx, day, mode: "replay", area });
      break;
    }
    case "archive":
      lazy(loadArchive, (m) => m.renderArchive(ctx));
      return void document.documentElement.removeAttribute("data-shell"); // (lazy() ends the start-up itself)
    case "admin":
      if (parts[1] === "play") {
        const day = num(parts[2]);
        if (!admin.unlocked || !(day >= 1)) return (location.hash = "#/admin");
        cleanup = renderGame({ ...ctx, day, mode: "test", area });
      } else {
        lazy(loadAdmin, (m) => m.renderAdmin({ ...ctx, day: num(parts[1]) }));
        return void document.documentElement.removeAttribute("data-shell");
      }
      break;
    default:
      location.hash = "#/";
  }
  document.documentElement.removeAttribute("data-shell");
  booted();
}

function paintSfx() {
  const b = document.querySelector('[data-action="sfx"]');
  b.innerHTML = icon(sfx.muted ? "sound-off" : "sound-on");
  b.setAttribute("aria-label", sfx.muted ? "Sound effects off" : "Sound effects on");
}

document.addEventListener("click", (e) => {
  const action = e.target.closest("[data-action]")?.dataset.action;
  if (action === "help") showHelp();
  if (action === "stats") showStats();
  if (action === "credits") showCredits();
  if (action === "sfx") {
    sfx.toggle();
    paintSfx();
    sfx.tap();
  }
  const adminAction = e.target.closest("[data-admin-action]");
  if (adminAction?.dataset.adminAction === "restart") {
    admin.resetTestGame(Number(adminAction.dataset.day), store.area);
    route();
  }
});

window.addEventListener("duskhunt:help", () => showHelp());
// A new part of the world: the same page, drawn again for it. A replay is of one part's day, so it
// goes back to today's animal instead.
window.addEventListener("duskhunt:area", () => (location.hash.startsWith("#/replay/") ? (location.hash = "#/") : route()));
window.addEventListener("hashchange", route);

// A tab left open overnight still shows yesterday: its start screen would start yesterday's animal,
// and its results would count down to a midnight that has passed. When the player is back and the
// date has changed, draw the page again for the new day. A game that's under way is left alone (it
// still counts for its own day, and its results then offer the new animal); so is an open popup.
function refreshForNewDay() {
  if (document.hidden || todayDay() === drawnDay || $("#modal-root").childElementCount) return;
  const page = location.hash.replace(/^#\/?/, "").split("/")[0];
  if (page && page !== "archive") return; // one past day, a replay, admin: the same on any date
  const game = page ? null : store.game(drawnDay, store.area);
  if (game && game.status === "playing" && game.started) return;
  route();
}
document.addEventListener("visibilitychange", refreshForNewDay);
window.addEventListener("pageshow", refreshForNewDay);
window.addEventListener("focus", refreshForNewDay);
setInterval(refreshForNewDay, 60_000);

paintSfx();
flushPending();
route();
// Past days and the map are one tap away, so fetch them once the page is quiet.
whenIdle(() => Promise.all([loadArchive(), loadAreaPicker()]).catch(() => {}));
