// Everything a player keeps lives in localStorage. No accounts, no email.
import { todayDay } from "./util.js";
import { AREA_KEYS } from "./areas.js";

const KEY = "duskhunt:v1";
// Saves from the first release live under this key; load() moves them over once.
const LEGACY_KEY = "slowzoo:v1";

/** Where a game is saved: "28" for the whole world (as before parts of the world), "europe:28". The
 * published page's start-up script (tools/publish-site.mjs) reads today's game the same way. */
export const gameKey = (day, area = "world") => (area && area !== "world" ? `${area}:${day}` : String(day));

function blank() {
  return {
    player: crypto.randomUUID ? crypto.randomUUID() : `p-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`,
    seenHelp: false,
    sfxMuted: false,
    mode: "normal",
    games: {},
  };
}

let state = load();

function load() {
  try {
    let raw = localStorage.getItem(KEY);
    if (raw === null && (raw = localStorage.getItem(LEGACY_KEY)) !== null) {
      localStorage.setItem(KEY, raw);
      localStorage.removeItem(LEGACY_KEY);
    }
    const parsed = JSON.parse(raw);
    if (parsed && parsed.player && parsed.games) return parsed;
  } catch {}
  return blank();
}

function persist() {
  try {
    localStorage.setItem(KEY, JSON.stringify(state));
  } catch {}
}

export const store = {
  get player() {
    return state.player;
  },
  get seenHelp() {
    return state.seenHelp;
  },
  set seenHelp(v) {
    state.seenHelp = v;
    persist();
  },
  /** "easy" (the everyday name counts: "toad", "owl"), "normal" or "hard" (only the exact species counts). */
  get mode() {
    if (["easy", "normal", "hard"].includes(state.mode)) return state.mode;
    return state.hardMode ? "hard" : "normal"; // saved before easy mode existed
  },
  set mode(v) {
    state.mode = ["easy", "hard"].includes(v) ? v : "normal";
    delete state.hardMode;
    persist();
  },
  get sfxMuted() {
    return Boolean(state.sfxMuted);
  },
  set sfxMuted(v) {
    state.sfxMuted = v;
    persist();
  },

  /** The part of the world whose animals you hear (areas.js): "world", "europe", "asia"… */
  get area() {
    return AREA_KEYS.includes(state.area) ? state.area : "world";
  },
  set area(v) {
    if (!AREA_KEYS.includes(v)) return;
    state.area = v;
    persist();
  },

  /** Each part of the world has its own game each day. */
  game(day, area = "world") {
    return state.games[gameKey(day, area)] || null;
  },
  saveGame(game) {
    state.games[gameKey(game.day, game.area)] = game;
    persist();
  },
  deleteGame(day, area = "world") {
    delete state.games[gameKey(day, area)];
    persist();
  },
  allGames() {
    return state.games;
  },
  exportJson() {
    return JSON.stringify(state, null, 2);
  },
  reset() {
    state = blank();
    persist();
  },
};

export function newGame(day, live, area = "world") {
  const mode = store.mode;
  return { day, area, guesses: [], status: "playing", live, easy: mode === "easy", hard: mode === "hard", started: false, submitted: false, startedAt: Date.now(), finishedAt: null };
}

/** Personal stats only count games played on their own day ("live" games), in any part of the world:
 * the streak is about showing up each day, wherever you listen. */
export function personalStats() {
  const games = Object.values(state.games);
  const live = games.filter((g) => g.live && g.status !== "playing");
  const wins = live.filter((g) => g.status === "won");
  const dist = [0, 0, 0, 0, 0, 0, 0]; // [escaped, step1..step6]
  for (const g of live) dist[g.status === "won" ? g.guesses.length : 0]++;

  const finishedDays = new Set(live.map((g) => g.day));
  const today = todayDay();
  let current = 0;
  for (let d = finishedDays.has(today) ? today : today - 1; finishedDays.has(d); d--) current++;

  let max = 0;
  let run = 0;
  const sorted = [...finishedDays].sort((a, b) => a - b);
  sorted.forEach((d, i) => {
    run = i > 0 && sorted[i - 1] === d - 1 ? run + 1 : 1;
    max = Math.max(max, run);
  });

  return {
    played: live.length,
    wins: wins.length,
    winRate: live.length ? Math.round((wins.length / live.length) * 100) : 0,
    current,
    max,
    dist,
    archivePlayed: games.filter((g) => !g.live && g.status !== "playing").length,
  };
}
