// A part of the world's own scenery (its home, trees and plants) is built by scene.js from drawings
// that are fetched when the part is chosen, so it can't be in the page's first paint by itself. Once
// built, its markup is kept here (in localStorage), and the published page puts it back with a tiny
// inline script right after the landscape, before anything is drawn (tools/publish-site.mjs). A
// returning player's Europe is then there in the very first frame, like the whole world's scenery.
// This file stands alone (no imports), because that inline script is made from it.
//
// What is kept: { v, part, groups: [[selector, where, html]…], defs }.
//   v       the build the markup was made by (the scene element's data-v, set when publishing; the
//           dev page has none and keeps nothing, so edits to scene.js always show)
//   groups  the part's group for each layer of the picture, and where in that layer it goes
//   defs    the drawings (<path id="a-…">) those groups point at
const KEY = "duskhunt:scene";

/** Keeps a part's scenery for the next visit. Quietly does nothing if storage is full or off. */
export function keepScenery(v, part, groups, defs) {
  if (!v) return;
  try {
    localStorage.setItem(KEY, JSON.stringify({ v, part, groups, defs }));
  } catch {}
}

/** What is kept of `part`, if it was made by this build: { groups, defs }, or null. */
export function keptScenery(v, part) {
  try {
    if (!v || !part) return null;
    const kept = JSON.parse(localStorage.getItem(KEY) || "null");
    return kept && kept.v === v && kept.part === part && Array.isArray(kept.groups) && typeof kept.defs === "string" ? kept : null;
  } catch {
    return null;
  }
}

/** Puts the kept scenery of `part` into the landscape, if it was made by this build. True if it did. */
export function restoreScenery(svg, v, part) {
  try {
    const kept = svg && !svg.querySelector(`.ar[data-ar="${part}"]`) && keptScenery(v, part);
    if (!kept) return false;
    // All or nothing: every layer must be there before anything is added.
    const places = kept.groups.map(([where]) => svg.querySelector(where));
    const defs = svg.querySelector("#scene-art");
    if (!defs || places.some((el) => !el)) return false;
    kept.groups.forEach(([, at, html], i) => places[i].insertAdjacentHTML(at, html));
    defs.insertAdjacentHTML("beforeend", kept.defs);
    svg.classList.add("ar-in");
    return true;
  } catch {
    return false;
  }
}
