let closeCurrent = null;

/** Closes whatever modal is open, e.g. when the page changes underneath it. */
export function closeModal() {
  closeCurrent?.();
}

/** cls: extra classes for the dialog ("area-modal" is a wider one). */
export function openModal(title, bodyHtml, { onClose, onMount, cls = "" } = {}) {
  // One dialog opened from another (the map from "How it works"): the dimmed page stays dimmed,
  // instead of flashing bright between the two.
  const replacing = Boolean(closeCurrent);
  closeCurrent?.();
  const root = $("#modal-root");
  const opener = document.activeElement;
  root.innerHTML = `<div class="modal-backdrop${replacing ? " no-fade" : ""}" role="presentation">
    <section class="card modal ${cls}" role="dialog" aria-modal="true" aria-labelledby="modal-title">
      <div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" type="button" data-close aria-label="Close">${icon("close")}</button></div>
      ${bodyHtml}
    </section></div>`;
  const backdrop = $(".modal-backdrop", root);
  const extra = [];
  let closed = false;
  function close() {
    if (closed) return;
    closed = true;
    document.removeEventListener("keydown", onKey);
    extra.forEach((fn) => fn());
    closeCurrent = null;
    // It fades out (style.css) rather than vanishing in one frame: the whole dimmed page jumping
    // back to full brightness at once reads as a flash.
    backdrop.classList.add("closing");
    setTimeout(() => backdrop.remove(), 180);
    onClose?.();
    opener?.focus?.();
  }
  function onKey(e) {
    if (e.key === "Escape") close();
  }
  document.addEventListener("keydown", onKey);
  backdrop.addEventListener("click", (e) => {
    if (e.target === backdrop || e.target.closest("[data-close]")) close();
  });
  $("[data-close]", root).focus();
  const cleanup = onMount?.(root, close);
  if (cleanup) extra.push(cleanup);
  closeCurrent = close;
  return close;
}

const bars = (lv) => `<span class="closeness" data-lv="${lv}"><i></i><i></i><i></i><i></i></span>`;

export function showHelp() {
  const demo = demoPuzzle();
  let clip = null;
  openModal(
    "How it works",
    `<ol class="steps">
      <li>${icon("sun")}<span><b>One animal a day.</b> Same for everyone. You hear its call at <b>1/8 speed</b>, so it sounds deep and strange.</span></li>
      <li>${icon("search")}<span>Type any animal to guess. Breeds, nicknames and even a few silly things work.</span></li>
      <li>${icon("ffwd")}<span>Every miss speeds the sound up: 1/8× → 1/4× → 1/2× → 1×. And the sun goes down.</span></li>
      <li>${icon("moon")}<span>At dusk you'll see its shape on the ridge. At night the keeper lights a lantern. After six tries, it gets away.</span></li>
    </ol>
    <div class="kicker" style="margin-bottom:8px">How close was your guess?</div>
    <div class="legend">
      <div>${bars("kind")}<span><b>Right kind.</b> Arctic fox vs. red fox. Your first one each game is free.</span></div>
      <div>${bars("family")}<span><b>Same family.</b> Wolf vs. fox.</span></div>
      <div>${bars("order")}<span><b>Same order.</b> Both carnivores.</span></div>
      <div>${bars("class")}<span><b>Same class.</b> Both mammals.</span></div>
      <div>${bars("none")}<span><b>Not even close.</b></span></div>
    </div>
    <div class="callout" style="margin-bottom:14px"><b>Try it:</b> this is a cat.
      <div class="row wrap-row" style="margin-top:10px">
        <button class="btn btn-small grow" type="button" data-demo="0.125">${creature("snail")} At 1/8 speed</button>
        <button class="btn btn-small grow" type="button" data-demo="1">${creature("cheetah")} Real speed</button>
      </div>
    </div>
    <div class="mode-row"><div class="kicker">Where the animals live</div>${areaButton("in-card")}<p class="muted">Pick a part of the world and hear its animals. Each part has its own animal every day.</p></div>
    <div class="mode-row"><div class="kicker" style="margin-bottom:8px">Difficulty</div>${modePicker()}<p class="muted">Same sounds in every mode. A game you have already started keeps its mode.</p></div>
    <p class="muted" style="font-size:13px;margin:0 0 14px">Headphones are best. Slowed sounds get deep, so keep the volume comfortable. A new animal wakes up every midnight. <button type="button" class="linklike" data-action="credits">Picture credits</button></p>
    <button class="btn btn-dark btn-block" type="button" data-close>Got it</button>`,
    {
      onClose: () => (store.seenHelp = true),
      onMount: (root) => {
        $$("[data-demo]", root).forEach((b) =>
          b.addEventListener("click", async () => {
            try {
              clip = clip || (await loadClip(demo.sound));
              clip.play(Number(b.dataset.demo));
            } catch {
              b.textContent = "Couldn't load";
            }
          })
        );
        $$(".btn .cr", root).forEach((c) => (c.style.cssText = "width:26px;height:26px"));
        return () => clip?.stop();
      },
    }
  );
}

export function showStats() {
  const s = personalStats();
  // dist: [got away, try1..try6] → found on try 1…6, then got away.
  const counts = [...s.dist.slice(1), s.dist[0]];
  openModal(
    "Keeper's logbook",
    `<div class="stats-grid">
      <div class="stat"><b>${s.played}</b><span>played</span></div>
      <div class="stat"><b>${s.winRate}%</b><span>found</span></div>
      <div class="stat"><b>${s.current}</b><span>streak</span></div>
      <div class="stat"><b>${s.max}</b><span>best</span></div>
    </div>
    ${s.played ? `<div class="kicker" style="margin-bottom:10px">How you usually find them</div>
    <div class="logbook-chart">${skyChart(counts, { label: "Your logbook" })}</div>` : ""}
    <p class="muted" style="font-size:13px;margin:14px 0 0">${s.played ? "Counts games played on their own day." : "Play today's animal to start your logbook."}${s.archivePlayed ? ` You've also finished ${s.archivePlayed} from the archive.` : ""}</p>`
  );
}

// ---------- Picture credits ----------

const LICENSE_URL = {
  "CC0 1.0": "https://creativecommons.org/publicdomain/zero/1.0/",
  "Public domain": "https://creativecommons.org/publicdomain/mark/1.0/",
  "CC BY 4.0": "https://creativecommons.org/licenses/by/4.0/",
  "CC BY 3.0": "https://creativecommons.org/licenses/by/3.0/",
  "CC BY-SA 4.0": "https://creativecommons.org/licenses/by-sa/4.0/",
  "CC BY-SA 3.0": "https://creativecommons.org/licenses/by-sa/3.0/",
};

/** Who drew the pictures, and under which licence: the animal silhouettes (shapes/credits.json,
 * written by tools/silhouettes/build.mjs) and the landscape's trees, homes and props
 * (shapes/scene-credits.json, written by tools/scene-art.mjs). */
export function showCredits() {
  openModal("Picture credits", `<div class="credits" id="credits"><p class="muted">Fetching the list…</p></div>`, {
    cls: "credits-modal",
    onMount: (root) => {
      const box = $("#credits", root);
      const get = (file) => fetch(file).then((r) => (r.ok ? r.json() : Promise.reject(new Error(String(r.status)))));
      const link = (href, text, title = "") => `<a href="${href}" target="_blank" rel="noopener"${title ? ` title="${esc(title)}"` : ""}>${text}</a>`;
      const said = (name) => esc(name.replaceAll("-", " "));
      // One block per artist and licence, the longest lists first.
      const groups = (items, each) => {
        const by = new Map();
        for (const c of items) {
          const key = JSON.stringify([c.by || "Unknown", c.l]);
          if (!by.has(key)) by.set(key, []);
          by.get(key).push(c);
        }
        return `<div class="cr-list">${[...by]
          .sort((x, y) => y[1].length - x[1].length || x[0].localeCompare(y[0]))
          .map(([key, list]) => {
            const [who, l] = JSON.parse(key);
            return `<div class="cr-group"><div class="cr-by"><b>${esc(who)}</b> · ${link(LICENSE_URL[l] || "https://creativecommons.org/", esc(l))}</div><div class="cr-names">${list.map(each).join(", ")}</div></div>`;
          })
          .join("")}</div>`;
      };
      const phylo = (c) => `${link(`https://www.phylopic.org/images/${c.id}`, said(c.name), c.t)}${c.m ? "&nbsp;↔" : ""}`;
      // The landscape's list is small and may be missing on an old stored copy: the rest still shows.
      Promise.all([get("shapes/credits.json"), get("shapes/scene-credits.json").catch(() => ({}))])
        .then(([all, scene]) => {
          const animals = Object.entries(all).filter(([, c]) => c.id).map(([name, c]) => ({ name, ...c })); // the Phosphor icons are thanked further down
          const scenery = Object.entries(scene).filter(([, c]) => !c.same).map(([name, c]) => ({ name, ...c })); // the owl and the bat are among the animals
          const plants = scenery.filter((c) => c.id);
          const built = scenery.filter((c) => c.gi);
          box.innerHTML = `<p>The ${animals.length} animal silhouettes come from ${link("https://www.phylopic.org", "PhyloPic")}, where biologists and illustrators share their drawings. Each was resized to fit; those marked ↔ were also mirrored. Thank you to everyone below.</p>
            ${groups(animals, phylo)}
            ${plants.length + built.length ? `<h3>The landscape</h3>` : ""}
            ${plants.length ? `<p>Its trees and plants are PhyloPic silhouettes as well, resized and with their outlines simplified; roots below the ground were cut off.</p>${groups(plants, phylo)}` : ""}
            ${built.length ? `<p>The homes, the keeper, the lantern and everything else people built are icons from ${link("https://game-icons.net", "Game-icons.net")}, recoloured and resized; some lost a part (a sun, a flower pot) or had parts set moving (the mill's sails, the fire).</p>${groups(built, (c) => link(`https://game-icons.net/1x1/${c.gi}.html`, said(c.name), c.t))}` : ""}
            <p>The icons on buttons, and the pictures for things that aren't animals, are ${link("https://phosphoricons.com", "Phosphor Icons")} (MIT licence).</p>
            <p>Recordings, photos and texts are credited under each day's animal.</p>`;
        })
        .catch(() => {
          box.innerHTML = `<p class="muted">The list couldn't be fetched just now. The silhouettes are from ${link("https://www.phylopic.org", "PhyloPic")}, the landscape's buildings from ${link("https://game-icons.net", "Game-icons.net")} (CC BY 3.0) and the icons from ${link("https://phosphoricons.com", "Phosphor Icons")}.</p>`;
        });
    },
  });
}
